<?php
declare(strict_types=1);
$root=__DIR__;$checks=['PHP >= 8.2'=>version_compare(PHP_VERSION,'8.2.0','>=')];foreach(['pdo_mysql','openssl','mbstring','curl','fileinfo','json'] as $ext)$checks['ext-'.$ext]=extension_loaded($ext);$checks['config/app.php']=is_file($root.'/config/app.php');$checks['config/database.php']=is_file($root.'/config/database.php');$checks['storage writable']=is_dir($root.'/storage')&&is_writable($root.'/storage');$checks['install lock']=is_file($root.'/storage/installed.lock');if($checks['config/database.php']){try{$c=require $root.'/config/database.php';$pdo=new PDO("mysql:host={$c['host']};port=".($c['port']??3306).";dbname={$c['database']};charset=utf8mb4",$c['username'],$c['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false]);$checks['database connection']=(bool)$pdo->query('SELECT 1')->fetchColumn();}catch(Throwable){$checks['database connection']=false;}}foreach($checks as $name=>$ok)echo ($ok?'PASS ':'FAIL ').$name.PHP_EOL;exit(in_array(false,$checks,true)?1:0);
